package net.battlespades.bot;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.world.MetadataDocument;
import static net.battlespades.bot.BotFoundationsTest.*;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.RecoveryPlanning.*;
import static net.battlespades.bot.BotPlayerTestData.player;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class BotRecoveryTest {
 static final Map<String,Object> SOURCE=read();
 static Map<String,Object> read() {try(var in=Objects.requireNonNull(BotRecoveryTest.class.getResourceAsStream("/golden/bot-recovery.json"))) {var r=map(MetadataDocument.json(new String(in.readAllBytes(),StandardCharsets.UTF_8)));return map(expand(r,list(r.get("definitions"))));}catch(IOException e){throw new UncheckedIOException(e);}}
 static Object expand(Object v,List<?> defs) {if(v instanceof Map<?,?> m){if(m.size()==1&&m.containsKey("$ref"))return expand(defs.get(integer(m.get("$ref"))),defs);var r=new LinkedHashMap<String,Object>();m.forEach((k,x)->{if(!k.equals("definitions"))r.put(k.toString(),expand(x,defs));});return r;}if(v instanceof List<?> l)return l.stream().map(x->expand(x,defs)).toList();return v;}
 static Object observe(Object v) {if(v instanceof Double d&&!Double.isFinite(d))return d>0?"infinity":"-infinity";if(v instanceof Cell c)return List.of(c.x(),c.y(),c.z());if(v instanceof Vector p)return List.of(p.x(),p.y(),p.z());if(v instanceof Move m)return Arrays.asList(observe(m.step()),m.cost(),m.spent(),m.dug());if(v instanceof Enum<?> e)return e.name().toLowerCase(Locale.ROOT);if(v instanceof Record r){var out=new LinkedHashMap<String,Object>();try{for(var c:r.getClass().getRecordComponents())out.put(c.getName().replaceAll("([a-z0-9])([A-Z])","$1_$2").toLowerCase(Locale.ROOT),observe(c.getAccessor().invoke(r)));}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}return out;}if(v instanceof Collection<?> c)return c.stream().map(BotRecoveryTest::observe).toList();return v;}
 static void matches(Object expected,Object actual){equal(expected,observe(actual));}
 static Vector vec(Object o){return o==null?null:vector(o);}
 static Abilities abilities(Object o){var a=map(o);var d=a.get("dig");return new Abilities(d==null?null:BotDigProfile.navigation(integer(map(d).get("tool_id"))).orElseThrow(),integer(a.get("blocks")),bool(a.get("can_build")));}
 static Plan plan(Object o){if(o==null)return null;var p=map(o);return new Plan(list(p.get("steps")).stream().map(v->{var s=map(v);return new Step(Kind.valueOf(string(s.get("kind")).toUpperCase(Locale.ROOT)),cell(s.get("source")),cell(s.get("destination")),list(s.get("dig_cells")).stream().map(BotFoundationsTest::cell).toList(),list(s.get("build_cells")).stream().map(BotFoundationsTest::cell).toList());}).toList(),real(p.get("cost")),integer(p.get("blocks")),integer(p.get("swings")),integer(p.get("expansions")),real(p.get("seconds")));}
 static BotNavigationWorld world()throws Exception{var w=new BotNavigationWorld();w.load(new MapSnapshot(7,0,BotNavigationTest.raw(SOURCE.get("raw_zlib")),"tdm","",List.of(),"retail"));return w;}
 static void delta(BotNavigationWorld w,Object o){var s=map(o);w.apply(new WorldDelta(7,number(s.get("version")),list(s.get("cells")).stream().map(v->{var a=list(v);return new VoxelChange(integer(a.get(0)),integer(a.get(1)),integer(a.get(2)),bool(a.get(3)),integer(a.get(4)),real(a.get(5)));}).toList()));}
 @Test void geometryAndToolBudgetsMatchUnchangedSource()throws Exception{var w=world();var rw=reader(w);var start=new Cell(245,245,100);for(var o:list(SOURCE.get("nodes"))){var r=map(o);matches(r.get("node"),node(vector(r.get("position"))));}for(var o:list(SOURCE.get("mix"))){var r=map(o);matches(r.get("result"),RecoverySkill.mix(list(r.get("values")).stream().mapToLong(BotFoundationsTest::number).toArray()));}for(var o:list(SOURCE.get("geometry"))){var t=map(o);delta(w,t.get("scene"));for(var v:list(t.get("queries"))){var q=map(v);var a=abilities(q.get("abilities"));var required=list(q.get("required")).stream().map(BotFoundationsTest::cell).toList();var protect=list(q.get("protected")).stream().map(BotFoundationsTest::cell).toList();if(a.dig()!=null)matches(q.get("aims"),digAims(rw,required,protect,a.dig()));matches(q.get("swings"),estimateSwings(rw,required,protect,a.dig()));matches(q.get("typical"),typicalLevelCost(a));for(var m:list(q.get("moves"))){var r=map(m);matches(r.get("result"),move(rw,a,start,Kind.valueOf(string(r.get("kind")).toUpperCase(Locale.ROOT)),integer(r.get("dx")),integer(r.get("dy")),a.blocks(),Set.of()));}matches(q.get("pillar"),primitive(rw,start,new Vector(1,0,0),4,a,Kind.PILLAR));matches(q.get("stairs"),primitive(rw,start,new Vector(1,0,0),4,a,Kind.STAIR));matches(q.get("bridge"),primitive(rw,start,new Vector(1,0,0),12,a,Kind.BRIDGE));matches(q.get("gap"),gapBridge(rw,new Vector(245.5,245.5,97.75),new Vector(260.5,245.5,97.75),a,16,2));matches(q.get("quick"),quickClimb(w,start,a,12));}}}
 @Test void retainedSearchMatchesEverySourceSliceAndFinalPlan()throws Exception{var w=world();for(var o:list(SOURCE.get("searches"))){var t=map(o);delta(w,t.get("scene"));for(var v:list(t.get("queries"))){var q=map(v);var n=new AtomicInteger();var a=new Abilities(q.get("tool")==null?null:BotDigProfile.navigation(integer(q.get("tool"))).orElseThrow(),integer(q.get("blocks")),true);var search=new Search(reader(w),new Cell(245,245,100),Goal.toward(vector(q.get("target")),1.5),a,18,350,false,null,Set.of(),()->n.getAndIncrement()*.02);for(var slice:list(q.get("slices"))){var s=map(slice);assertEquals(s.get("status"),search.advance(.012));assertEquals(integer(s.get("expansions")),search.expansions());}matches(q.get("plan"),search.plan());}}}
 static void executor(BotNavigationWorld w,Map<String,Object> trace,Plan p,boolean failure){var skill=new RecoverySkill(p,failure?"failure":"fixture",100,failure?0:23758,failure?.5:.7,.2,failure||bool(trace.get("backwards")),100);int i=0;for(var o:list(trace.get("events"))){var e=map(o);if(e.get("op").equals("delta")){delta(w,e);continue;}try{matches(e.get("result"),skill.update(player(e.get("observer")),reader(w),real(e.get("now")),abilities(e.getOrDefault("abilities",trace.get("abilities")))));matches(e.get("state"),skill.snapshot());}catch(AssertionError x){throw new AssertionError("executor "+trace.get("name")+" event "+i,x);}i++;}}
 @Test void executorRevalidatesTerrainAndRetainsFeedbackTiming()throws Exception{var w=world();for(var o:list(SOURCE.get("executors"))){var t=map(o);delta(w,t.get("scene"));executor(w,t,plan(t.get("plan")),false);}var f=map(SOURCE.get("failure_executors"));delta(w,f.get("scene"));for(var o:list(f.get("cases")))executor(w,map(o),plan(f.get("plan")),true);}
 static void driver(BotNavigationWorld w,List<?> rows){var clock=new AtomicInteger();var d=new RecoveryDriver(w,()->clock.getAndIncrement()*.02);int i=0;for(var o:rows){var e=map(o);String op=string(e.get("op"));if(op.equals("delta")){delta(w,e);continue;}var p=player(e.get("observer"));var profile=profile(e.get("profile"));double now=real(e.get("now"));var goal=vec(e.get("goal"));try{Object result=switch(op){case "cancel"->{d.cancel(p);yield null;}case "step"->d.step(p,profile,now);case "stuck"->d.considerStuck(p,profile,now,goal,bool(e.get("climb")));case "gap"->d.considerGap(p,profile,now,new Vector(260.5,245.5,97.75),16);case "water"->d.considerWater(p,profile,now,goal,Double.POSITIVE_INFINITY,true);case "left"->{d.leftWater(p,now);yield null;}case "request"->{var r=map(e.get("request"));yield d.request(p,profile,new RecoveryDriver.Request(string(r.get("kind")),vec(r.get("target")),vec(r.get("direction")),integer(r.get("levels")),integer(r.get("length"))),now);}default->throw new IllegalArgumentException(op);};matches(e.get("result"),result);matches(e.get("state"),d.snapshot(p));matches(e.get("active"),d.active(p));matches(e.get("description"),d.describe(p));matches(e.get("awaits"),d.climbAwaitsWalkAnswer(p,now,goal));matches(e.get("metrics"),d.metrics());matches(e.get("events"),d.events());matches(e.get("slots"),d.slotCount());if(e.containsKey("quick")){matches(e.get("quick"),quickClimb(w,node(p.position()),Abilities.from(p),28));matches(e.get("swim"),RecoveryDriver.swimSecondsToShore(w,p,goal));}}catch(AssertionError x){throw new AssertionError("driver "+op+" event "+i,x);}i++;}}
 @Test void driverRetainsRequestsWatchdogsLifeAndWaterEpisodes()throws Exception{var w=world();for(var o:list(SOURCE.get("drivers"))){var t=map(o);delta(w,t.get("scene"));driver(w,list(t.get("events")));}var water=map(SOURCE.get("water_driver"));w=new BotNavigationWorld();var changes=list(water.get("initial")).stream().map(o->{var c=map(o);return new VoxelChange(integer(c.get("x")),integer(c.get("y")),integer(c.get("z")),bool(c.get("solid")),integer(c.get("color")),real(c.get("health")));}).toList();w.load(new MapSnapshot(8,0,BotNavigationTest.raw(water.get("raw_zlib")),"tdm","",changes,"retail"));driver(w,list(water.get("events")));}
 @Test void mutableRecoveryStateRejectsOtherWorkers()throws Exception{var d=new RecoveryDriver(new BotNavigationWorld());var p=new Plan(List.of(),0,0,0,0,0);var s=new RecoverySkill(p,"test",0,0,.5,.2,true,0);var count=new AtomicInteger();var t=new Thread(()->{for(Runnable r:List.<Runnable>of(d::reset,s::snapshot))try{r.run();}catch(IllegalStateException expected){count.incrementAndGet();}});t.start();t.join();assertEquals(2,count.get());}
}
